use vstd::prelude::*;

verus! {

    /// Returns true iff `a` is empty or all of its elements are equal.
    /// 
    /// Post‐conditions:
    ///   – if `result == true` then for all valid indices `i,j`, `a[i] == a[j]`
    ///   – if `result == false` then there exist valid indices `i,j` with `a[i] != a[j]`
    fn has_only_one_distinct_element(a: &Vec<i32>) -> (result: bool)
        ensures
            result
                ==> forall |i: usize, j: usize|
                        i < a.len() && j < a.len() ==> a[i] == a[j],
        ensures
            !result
              ==> exists |i: usize, j: usize|
                        i < a.len() && j < a.len() && a[i] != a[j],
    {
        let n = a.len();
        // If 0 or 1 element, vacuously all equal.
        if n <= 1 {
            return true;
        }
        let first = a[0];

        // Walk from i = 1 .. n−1, checking each against `first`.
        // Invariant: all a[0..i) are equal to `first`.
        let mut i: usize = 1;
        while i < n
            invariant 1 <= i && i <= n,
            invariant forall |j: usize| j < i ==> a[j] == first,
            decreases n - i,
        {
            if a[i] != first {
                // We have found two distinct elements: a[0] and a[i].
                proof {
                    // by definition of `first`
                    assert(a[0] == first);
                    // and by the `if` condition
                    assert(a[0] != a[i]);
                }
                return false;
            }
            i += 1;
        }

        // If we reach here, i == n and the invariant tells us
        // ∀ j < n. a[j] == first.  Hence any two are equal.
        proof {
            assert forall |i0: usize, j0: usize| i0 < n && j0 < n implies a[i0] == a[j0] by {
                // from the invariant:
                assert(a[i0] == first);
                assert(a[j0] == first);
            };
        }
        return true;
    }
}

fn main() {
    // example smoke‐test
    let v1 = Vec::from_slice(&[7,7,7]);
    let v2 = Vec::from_slice(&[1,2,1]);
    assert!(has_only_one_distinct_element(&v1));
    assert!(!has_only_one_distinct_element(&v2));
}